/* ===== PS01-MAC 结构观感（v3.41.0；v3.42.0 token 化随深浅主题）===== */
/* 侧栏：macOS 源列表 —— 胶囊分段（文件/大纲）+ accent 圆角选中条 */
QWidget#tabcap {
  background: {seg_bg};
  border-radius: 7px;
}
QWidget#tabcap QToolButton {
  border: none;
  border-radius: 5px;
  background: transparent;
  color: {seg_item_text};
  padding: 4px 14px;
  font-weight: 500;
}
QWidget#tabcap QToolButton:hover {
  color: {text};
}
QWidget#tabcap QToolButton:checked {
  background: {tab_sel_bg};
  color: {text};
  border: 1px solid {seg_bg};
}
#sidebar QListWidget::item,
#sidebar QTreeWidget::item {
  border-radius: 6px;
  margin: 1px 6px;
  padding: 2px 4px;
  color: {text};
}
#sidebar QListWidget::item:hover,
#sidebar QTreeWidget::item:hover {
  background: {hover_bg};
}
#sidebar QListWidget::item:selected,
#sidebar QTreeWidget::item:selected {
  background: {accent};
  color: #ffffff;
}
#sidebar QListWidget::item:selected:disabled {
  background: transparent;
  color: {text_muted};
}
/* 标签栏：mac 顶圆角页签（活动标签连编辑区）*/
QWidget#tabstrip {
  background: {bg_soft};
}
QTabBar::tab:!selected {
  background: transparent;
  color: {tab_text};
  border: 1px solid transparent;
  border-top-left-radius: 8px;
  border-top-right-radius: 8px;
  padding: 5px 14px 4px;
  margin-right: 2px;
}
QTabBar::tab:hover {
  background: {seg_bg};
}
QTabBar::tab:selected {
  background: {tab_sel_bg};
  color: {tab_sel_text};
  border: 1px solid {border};
  border-bottom: none;
}
QTabBar::close-button {
  subcontrol-position: right;
}
/* 状态栏：26px 分格行 */
QStatusBar {
  background: {bg_soft};
  border-top: 1px solid {border};
  color: {text_muted};
}
QStatusBar::item {
  border: none;
  border-left: 1px solid {status_sep};
}
QStatusBar QLabel {
  background: transparent;
  padding: 0 6px;
}
/* 工具按钮 / 输入框大圆角观感 */
QPushButton {
  border-radius: 6px;
}
QLineEdit, QComboBox, QSpinBox {
  border-radius: 6px;
}
